(* [comment removed for export] *)
Definition both_mem_facts_w (w : bool) : list mfact := if w then both_mem_facts_w1 else both_mem_facts_w2.
Definition both_pure_facts_w (w : bool) : list pfact := if w then both_pure_facts_w1 else both_pure_facts_w2.

(* [comment removed for export] *)
Definition clipw (r : Z * Z) : Z * Z := (fst r, Z.min (snd r) (2 ^ 64)).
Definition amain_windows (V : nat -> Z) : gwin := List.map clipw (allow_of AM_SHOFF V both_vis).

(* [comment removed for export] *)
Definition AMAIN_R0 : Z := target_alloc_limit - both_eager - both_abytes.

(* [comment removed for export] *)
Definition amain_gwin (V : nat -> Z) (m : word -> option byte) (mo : Model) : Prop :=
  forall x : word, in_winb (amain_windows V) x = true -> lzf mo x = true ->
    (0x7fff7000 <= bv_unsigned x < 0x8fff7000
     \/ 0x2008fff7000 <= bv_unsigned x < 0x10007fff8000
     \/ 4096 * V IX_SSTORE <= bv_unsigned x < 4096 * V IX_SSTORE + 8388608) ->
    m x <> None.

(* [comment removed for export] *)
(* [comment removed for export] *)

Definition a_main_entry (w : bool) (V : nat -> Z) (sp0 brk0 : word) (rdraw : EntryDraw) (argv envp : list (list byte)) (uid hw : word)
           (fs : Fs.Fs) (regs : bvmap 5 word) (m : word -> option byte) (mo : Model) (g : lghost) : Prop :=
  amain_vars V sp0 brk0 rdraw argv envp uid hw
  /\ amain_regs V sp0 regs
  /\ Forall (mfact_ok bsegs V m) (both_mem_facts ++ both_mem_facts_w w)
  /\ Forall (pfact_ok V) (both_pure_facts ++ both_pure_facts_w w)
  /\ amain_args sp0 rdraw argv envp uid hw m
  /\ amodel V sp0 fs mo
  /\ g = mkG (amain_windows V) AMAIN_R0
  /\ amain_gwin V m mo
  (* [comment removed for export] *)
  /\ (forall a : word, 0x800000000000 <= bv_unsigned a -> m a = None).

(* [comment removed for export] *)
Definition a_main_stmt : Prop :=
  forall (ACEIL : Ceil) (w : bool) (V : nat -> Z) (sp0 brk0 mbase : word) (rdraw : EntryDraw) (argv envp : list (list byte))
         (uid hw : word) (fs : Fs.Fs) (regs : bvmap 5 word) (m : word -> option byte) (mo : Model) (g : lghost),
    valid_sp sp0 -> valid_brk bsegs brk0 -> valid_mmap_base mbase ->
    valid_argv argv -> valid_envp envp -> valid_fs fs -> entry_stack_fits sp0 argv envp -> valid_id uid -> valid_hwcap hw ->
    alloc_ceiling = bv_unsigned sp0 - 8388608 ->
    a_main_entry w V sp0 brk0 rdraw argv envp uid hw fs regs m mo g ->
    LRZ bsegs (MS (mkR_of regs) bvmap_empty (wz AM_MAIN) (Z_to_bv 32 0) None m (seg_rom bsegs)) mo g (spec04 argv fs).
